type SourcePostingsParams struct {
	SourceModule *string
	SourceKind   *string
	SourceID     *int64
}

type SourcePostingsRow struct {
	VoucherID          int64
	LineNo             int32
	AccountID          int32
	Amount             string
	TaxCodeID          *int32
	TaxRole            *string
	TaxBase            string
	TaxSpecification   *string
	CustomerID         *int32
	SupplierID         *int64
	OpenItemID         *int64
	ProjectID          *int32
	Description        string
	PostingRuleID      *int32
	PostingRuleVersion *int32
}

// SourcePostings is the postings of the voucher a source posted as, with
// the voucher's id: what an undo or a removal turns back line for line
// (R15). No rows when the source has no voucher.
func (q *Queries) SourcePostings(ctx context.Context, arg SourcePostingsParams) ([]SourcePostingsRow, error) {
	rows, err := q.db.Query(ctx, sourcePostings, arg.SourceModule, arg.SourceKind, arg.SourceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SourcePostingsRow
	for rows.Next() {
		var i SourcePostingsRow
		if err := rows.Scan(
			&i.VoucherID,
			&i.LineNo,
			&i.AccountID,
			&i.Amount,
			&i.TaxCodeID,
			&i.TaxRole,
			&i.TaxBase,
			&i.TaxSpecification,
			&i.CustomerID,
			&i.SupplierID,
			&i.OpenItemID,
			&i.ProjectID,
			&i.Description,
			&i.PostingRuleID,
			&i.PostingRuleVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const takeRequest = `-- name: TakeRequest :exec
DELETE FROM accounting.catchup_requests WHERE stream = $1
`

func (q *Queries) TakeRequest(ctx context.Context, stream string) error {
	_, err := q.db.Exec(ctx, takeRequest, stream)
	return err
}

